export const collectionIds=['walnut','sienna','hoi-an','madison','trianon','wellington'];
export function parseRoute(hash){try{const url=new URL(String(hash||'#/').replace(/^#/,''),'https://atelier.local'),segments=url.pathname.split('/').filter(Boolean),page=segments[0]||'home';if(!['home','collections','products','gallery','materials','studio'].includes(page))return {page:'not-found'};const collection=segments[1]||url.searchParams.get('collection')||null;if(collection&&!collectionIds.includes(collection))return {page:'not-found'};if(segments.length>2||(['home','studio','products'].includes(page)&&segments.length>1))return {page:'not-found'};return{page:page==='collections'&&collection?'collection':page,collection,product:url.searchParams.get('product'),load:url.searchParams.get('load')==='1'};}catch{return {page:'not-found'};}}
export function filterProducts(products,{collection='all',category='all',query=''}={}){const q=String(query).trim().toLowerCase();return products.filter(p=>(collection==='all'||p.collection===collection)&&(category==='all'||p.category===category)&&(!q||(p.name+' '+p.sku+' '+p.collectionName).toLowerCase().includes(q)));}
export function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
